 manifest=json.loads((F/'manifest.json').read_text());plan=json.loads((F/'selection.json').read_text());worlds=json.loads((F/'selected_worlds.json').read_text());allworlds=json.loads((E/'executions/experiment_v1/main_worlds.json').read_text());families=['compute_plan','delivery_route','archive_retention','reliability_testing'];expected=[w for f in families for w in [w for w in allworlds if w['family']==f and w['split'] in ['test','family_test']][:6]];requests={};meta={}
