 checks.update({'all_source_assignment_links':bool(mapping),'24cells_per_world':set(counts.values())=={24},'pilot4worlds_one_per_family':len(pilotworld)==4 and len({p['family'] for p in plan if p['pilot']})==4,'colocated_orders6each':orders=={0:6,1:6,2:6,3:6},'only_native_mode_cap_id_change':bool(request_changes)})
 spec=importlib.util.spec_from_file_location('native_contract_under_review',F/'native_comparison_v1.py');module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);tok=module.tokenizer();a=tok.encode('A',add_special_tokens=False);b=tok.encode('B',add_special_tokens=False);assert a==[32] and b==[33] and tok.eos_token_id==151645
 def row(ids,eos=True):return {'generated_token_ids':ids,'ended_with_eos':eos}
 cases=[('valid_A',[151667,151668,32,151645],True,True,'A'),('reasoning_A_final_B',[151667,32,151668,33,151645],True,True,'B'),('missing_closer',[151667,32,151645],True,False,None),('multiple_closers',[151667,151668,151668,32,151645],True,False,None),('missing_eos',[151667,151668,32],False,False,None),('false_eos_flag',[151667,151668,32,151645],False,False,None),('wrong_last_token',[151667,151668,32],True,False,None),('extra_visible_text',[151667,151668]+tok.encode('A because it is safe',add_special_tokens=False)+[151645],True,False,None),('EOS_exactly_cap',[151667]+[32]*4092+[151668,32,151645],True,True,'A'),('over_cap',[151667]+[32]*4093+[151668,32,151645],True,False,None)]
